mapper.select:
SELECT * from(
select ROW_NUMBER() OVER(ORDER BY T.head_budget_date desc,dept_budget_no desc) RNUM, T.*
from (
    SELECT * 
    FROM vw_head_budget_with_balance 
    where 1=1

			AND head_budget_year=#{year}


			AND head_budget_ty = #{type} 

			)T
	) 
	where  RNUM BETWEEN (#{currentPage} * 10) - (10 - 1) AND (#{currentPage} * 10)

mapper.update:
update head_budget
set head_budget_year=#{headBudgetYear},
	head_budget=#{headBudget},
	head_budget_content=#{headBudgetContent}
where dept_budget_no=#{deptBudgetNo}

mapper.select:
select count(*) from store_budget
where 1=1
and store_no=#{storeNo}

	AND STORE_BUDGET_YEAR=#{year}


	AND STORE_budget_ty = #{type}


select * from(
	select T.* ,ROW_NUMBER() OVER( ORDER BY T.store_budget_date desc, T.store_budget_no desc) RNUM
	from (
		select * from 
		vw_store_budget_with_balance 
		where store_no=#{storeNo}

			and store_budget_ty=#{type} 


			AND STORE_BUDGET_YEAR=#{year}
		)T
	)
	where rnum  BETWEEN (#{currentPage} * 10) - (10 - 1) AND (#{currentPage} * 10)

mapper.update:
update store_budget
set store_budget_year=#{storeBudgetYear},
	store_budget=#{storeBudget},
	store_budget_content=#{storeBudgetContent}
where store_budget_no=#{storeBudgetNo}
